import{_ as r,c as i,j as t,a as n,G as s,a2 as d,B as o,o as l}from"./chunks/framework.rHWNTPhC.js";const b=JSON.parse('{"title":"Städtische Referenzarchitektur für das Frontend","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-frontend-template.md","filePath":"technik/adr/adr-frontend-template.md"}'),h={name:"technik/adr/adr-frontend-template.md"};function u(m,e,c,p,g,f){const a=o("adr-status");return l(),i("div",null,[e[0]||(e[0]=t("h1",{id:"stadtische-referenzarchitektur-fur-das-frontend",tabindex:"-1"},[n("Städtische Referenzarchitektur für das Frontend "),t("a",{class:"header-anchor",href:"#stadtische-referenzarchitektur-fur-das-frontend","aria-label":'Permalink to "Städtische Referenzarchitektur für das Frontend"'},"​")],-1)),e[1]||(e[1]=t("h2",{id:"status",tabindex:"-1"},[n("Status "),t("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),s(a,{status:"accepted"}),e[2]||(e[2]=d('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Es gibt zwei verschiedene Templates der städtischen Referenzarchitektur. Einmal den internen maven-Archetype, bei welchem das Frontend Teil des ApiGateway ist und zum Anderen das <a href="https://github.com/it-at-m/refarch-templates/tree/main" target="_blank" rel="noreferrer">Github-Template</a>, bei welchem das Frontend eigenständig ist und das ApiGateway als Docker-Image bereitgestellt wird.</p><p>In Bezug auf die Wartbarkeit und Komplexität sollte entschieden werden, welches Template für das WLS-Projekt besser geeignet ist.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Es wurden damals im alten Code einige Anpassungen am Gateway vorgenommen. Zum Beispiel wurden neue Filter hinzugefügt, User-Sessions in der Datenbank gespeichert und alle Daten wurden verschlüsselt übertragen.</p><p>Entscheidungskriterium ist, ob diese Änderungen dem generierten ApiGateway-Image des Github-Templates hinzugefügt werden können oder nicht. Es steht allerdings noch nicht fest, inwieweit diese Einstellungen übernommen oder ggf. abgelöst werden können, daher wurde sich darauf geeinigt, vorerst mit dem Github-Template und dem generierten ApiGateway zu arbeiten. Sollten im Nachhinein doch noch Änderungen am Gateway vorgenommen werden müssen, wird nicht auf das maven-Archetype-Template gewechselt, sondern der Source-Code des Images manuell zum Projekt hinzugefügt und angepasst.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><h3 id="positiv" tabindex="-1">positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;positiv&quot;">​</a></h3><p>Das Github-Template kommt mit aktuelleren Versionen der Dependencies. Die Wartung und Komplexität des Frontendprojekts gestaltet sich einfacher, da es ein kleineres Projekt ist.</p><h3 id="negativ" tabindex="-1">negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;negativ&quot;">​</a></h3><p>Sollten noch Änderungen am Gateway vorgenommen werden müssen, muss dieses im Nachhinein manuell erfolgen und könnte etwas mehr Aufwand erfordern.</p>',11))])}const w=r(h,[["render",u]]);export{b as __pageData,w as default};
